window.openCombinedNewTab = function() {
  const bytes = (state.viewerMode === "all")
    ? (state.processedResults?.combinedMasterPdfBytes || state.processedResults?.combinedPdfBytes)
    : (state.processedResults?.combinedIndividualPdfBytes || state.processedResults?.combinedPdfBytes);
  if (!bytes) {
    appendLog("Please run scan first to generate the document.", "warn");
    return;
  }
  const blob = new Blob([bytes], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    document.body.removeChild(a);
  }, 500);
};
window.openCombinedNewWindow = function() {
  window.openCombinedNewTab();
};
window.openVisitorNewWindow = function(targetKey) {
  const keyStr = String(targetKey);
  const item = state.processedResults?.individualPdfs.find(
    p => (p.visitor.uid && p.visitor.uid === keyStr) || String(p.visitor.no) === keyStr
  );
  if (!item || !item.pdfBytes) return;
  const blob = new Blob([item.pdfBytes], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener noreferrer";
  document.body.appendChild(a);
  a.click();
  setTimeout(() => document.body.removeChild(a), 500);
};
